#!/usr/bin/env bash
# NOREP deploy — köken'den temsilci/rep kaldır (server + mobil + desktop), müşteri odaklı. Regen. Idempotent.
set -e
cd /opt/krb-assessment
set -a; [ -f .env ] && . ./.env; set +a
PW="${POSTGRES_PASSWORD:-}"
if [ -f shells/saha.js ]; then SAHA=shells/saha.js; else SAHA=$(find . -maxdepth 3 -name saha.js -not -path '*/backups/*' -not -path '*/node_modules/*'|head -1); fi
KOK=shells/kokpit.html
[ -f "$SAHA" ] || { echo "HATA: saha.js yok"; exit 1; }
[ -f "$KOK" ] || { echo "HATA: kokpit.html yok"; exit 1; }
cp server_container.mjs server_container.mjs.bak.$(date +%s)
cp "$SAHA" "$SAHA.bak.$(date +%s)"
cp "$KOK" "$KOK.bak.$(date +%s)"

echo "== server =="; printf '%s' '' | base64 -d > fix_norep.py; python3 fix_norep.py
echo "== mobil =="; SDIR=$(dirname "$SAHA"); printf '%s' '' | base64 -d > "$SDIR/fix_norep_mobil.py"; ( cd "$SDIR" && python3 fix_norep_mobil.py ) && rm -f "$SDIR/fix_norep_mobil.py"
echo "== desktop =="; printf '%s' '' | base64 -d > shells/fix_norep_desktop.py; ( cd shells && python3 fix_norep_desktop.py ) && rm -f shells/fix_norep_desktop.py

echo "== syntax =="; node --check server_container.mjs && echo SERVER_OK; node --check "$SAHA" && echo SAHA_OK

echo "== bugünkü satırı sil (rep'siz yeniden üret) =="
docker exec -i -e PGPASSWORD="$PW" krb-assessment-postgres psql -U assessment_app -d assessment_platform -P pager=off -c "DELETE FROM bi_finansal_icgoru WHERE gun=CURRENT_DATE;"

docker build -t krb-assessment:secure .
docker compose up -d --force-recreate krb-assessment
echo "== 110sn bekle =="; sleep 110
echo "== köken müşteri (rep alanı OLMAMALI) =="
docker exec -i -e PGPASSWORD="$PW" krb-assessment-postgres psql -U assessment_app -d assessment_platform -P pager=off -F $'\t' -A <<'SQL'
SELECT left(t->>'ad',32) musteri, round((t->>'overdue')::numeric/1e6,1) net_M, (t ? 'rep')::text rep_alani_var
FROM bi_finansal_icgoru, jsonb_array_elements(baglam->'koken'->'top') t WHERE gun=CURRENT_DATE LIMIT 6;
SQL
echo "== içgörü başlıkları (temsilci geçmemeli) =="
docker exec -i -e PGPASSWORD="$PW" krb-assessment-postgres psql -U assessment_app -d assessment_platform -P pager=off -F $'\t' -A <<'SQL'
SELECT (e->>'siddet') siddet, left(e->>'baslik',54) baslik FROM bi_finansal_icgoru, jsonb_array_elements(icgoruler) e WHERE gun=CURRENT_DATE;
SQL
echo "== DONE =="
